/// <summary>
/// PaffH 01.10.25
/// </summary>
/// <param name = "_formRun">FormRun</param>
/// <returns>NDXBVEMailRequestControlCenterFormI</returns>
public static NDXBVEMailRequestControlCenterFormI getNDXBVEMailRequestControlCenterFormI(FormRun _formRun)
{
    NDXBVEMailRequestControlCenterFormI nDXBVEMailRequestControlCenterFormI;
    if (_formRun is NDXFormHandlerIncludedI)
    {
        NDXFormHandlerIncludedI nDXFormHandlerIncludedI = _formRun as NDXFormHandlerIncludedI;
        if (nDXFormHandlerIncludedI)
        {
            if (nDXFormHandlerIncludedI.parmFormhandler() is NDXBVEMailRequestControlCenterForm)
            {
                NDXBVEMailRequestControlCenterForm formHandler = nDXFormHandlerIncludedI.parmFormhandler();
                if (formHandler is NDXBVEMailRequestControlCenterFormI)
                {
                    nDXBVEMailRequestControlCenterFormI = formHandler as NDXBVEMailRequestControlCenterFormI;
                }
            }
        }
    }
    return nDXBVEMailRequestControlCenterFormI;
}

