/// <summary>
/// PaffH 13.11.25
/// </summary>
/// <param name = "_control">FormStaticTextControl</param>
private void setColorStaticTextControlLabel(FormStaticTextControl _control)
{
    _control.colorScheme(FormColorScheme::RGB);
    _control.backgroundColor(WinAPI::RGB2int(211,211,211));
}

/// <summary>
/// PaffH 13.11.25
/// </summary>
/// <param name = "_control">FormStaticTextControl</param>
/// <param name = "_setColor2">boolean (false)</param>
private void setColorStaticTextControlValue(FormStaticTextControl _control, boolean _setColor2 = false)
{
    _control.colorScheme(FormColorScheme::RGB);
    if (_setColor2)
    {
        _control.backgroundColor(WinAPI::RGB2int(255,0,0));
        _control.foregroundColor(WinAPI::RGB2int(255,255,0));

    }
    else
    {
        _control.backgroundColor(WinAPI::RGB2int(255,255,0));
        _control.foregroundColor(WinAPI::RGB2int(0,0,0));
    }
}

