/// <summary>
/// PaffH 04.09.25
/// last modified: PaffH 10.09.25
/// </summary>
/// <returns>dataareaid for bv request</returns>
public DataAreaId getCompanyFilter()
{
    nDXBVEMailRequestState = fdsNDXBVEMailRequestState.cursor();
    nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
    DataAreaId uk = nDXBVEMailRequestState.OrganisationDataAreaId ? nDXBVEMailRequestState.OrganisationDataAreaId : nDXBVEMailRequestHeader.ContactPersonDataAreaId;
    if (!uk)
    {
        this.addNote(NDXBVEMailRequestNotesEnum::AssignmentOrgCompanyMissing,
            "Der Kontakt konnte über das Outlook-Plugin nicht ermittelt werden.\nSomit ist das Organisations-UK nicht bekannt.",
            "Als Fallback wurde das UK [NDX] gewählt.\nBitte ordnen Sie im Tab:Organisation im Feld:[UK Organisaton] das korrekte UK zu.");
        //warning("@NDX:NDXOrganizationalUKMissing");
        uk = NDXHelperDataArea::DataAreaIdFromEnum(NDXDataAreaIdEnum::Niedax);
    }
    return uk;
}

/// <summary>
/// PaffH 19.08.25
/// last modified: PaffH 29.11.25
/// </summary>
/// <returns>NDXBVSearchContract</returns>
public NDXBVSearchContract fillContract()
{
    NDXBVSearchContract contract = new NDXBVSearchContract();

    dirPersonLookUp = fdsDirPersonLookUp.cursor();
    nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
    custTableDirPartyState = fdsCustTableDirPartyState.cursor();
    contactPersonLookUp = fdsContactPersonLookup.cursor();
    kCS_KBVBuildingProjectTable = fdsKCS_KBVBuildingProjectTable.cursor();
    custTableLookup = fdsCustTableLookup.cursor();
    nDXBVEMailRequestPerCompany = fdsNDXBVEMailRequestPerCompany.cursor();

    // Kontakt
    if (nDXBVEMailRequestHeader.ContactPersonLastName)
    {
        contract.parmContactName(nDXBVEMailRequestHeader.ContactPersonLastName);
        contract.parmOperatorContact(AVASqlOperator::Like);
        contract.parmContactPersonLastName(nDXBVEMailRequestHeader.ContactPersonLastName);
    }
    else if (dirPersonLookUp.Name)
    {
        contract.parmContactName(dirPersonLookUp.Name);
        contract.parmOperatorContact(AVASqlOperator::Like);
    }
    if (nDXBVEMailRequestHeader.ContactPersonFirstName)
    {
        contract.parmContactPersonFirstName(nDXBVEMailRequestHeader.ContactPersonFirstName);
    }

    if (contactPersonLookup)
    {
        contract.parmrecIdContactPerson(contactPersonLookup.RecId);
    }
    if (nDXBVEMailRequestHeader.ContactPersonEmail)
    {
        contract.parmContactPersonEmail(nDXBVEMailRequestHeader.ContactPersonEmail);
    }
    if (nDXBVEMailRequestHeader.ContactPersonTitle)
    {
        contract.parmContactPersonTitle(nDXBVEMailRequestHeader.ContactPersonTitle);
    }


    // LV
    nDXBVEMailRequestState = fdsNDXBVEMailRequestState.cursor();
    if (nDXBVEMailRequestState.RequestTenderProjectNameChangedManual)
    {
        contract.parmsubject(nDXBVEMailRequestState.RequestTenderProjectNameChangedManual);
        contract.parmOperatorSubject(AVASqlOperator::Like);
    }
    else if (nDXBVEMailRequestHeader.RequestTenderProjectName)
    {
        contract.parmsubject(nDXBVEMailRequestHeader.RequestTenderProjectName);
        contract.parmOperatorSubject(AVASqlOperator::Like);
    }

    // Anfrager
    if (nDXBVEMailRequestHeader.OrganisationName1 ||
        nDXBVEMailRequestHeader.OrganisationName2 ||
        nDXBVEMailRequestHeader.OrganisationName3)
    {
        contract.parmPartyName(nDXBVEMailRequestHeader.parmOrganisationName123());
    }
    else if (nDXBVEMailRequestState.RoleForBuildingProject == NDXRoleForBuildingProject::Customer && 
        nDXBVEMailRequestState.CustAccountManualSelected != '')
    {
        if (custTableDirPartyState.Name)
        {
            contract.parmPartyName(custTableDirPartyState.Name);
        }
    }

    // City
    if (nDXBVEMailRequestHeader.ProjectAddressCity)
    {
        contract.parmCity(nDXBVEMailRequestHeader.ProjectAddressCity);
        contract.parmOperatorCity(AVASqlOperator::Like);
    }

    // project zipcode
    if (nDXBVEMailRequestHeader.ProjectAddressZipCode)
    {
        contract.parmProjectAddressZipCode(nDXBVEMailRequestHeader.ProjectAddressZipCode);
    }

    // building project
    contract.parmBuildingProjectId(kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);

    // organisation (customer) of contact
    contract.parmCustAccount(custTableLookup.AccountNum);

    contract.parmDataAreaIdOrganisation(this.getCompanyFilter());

    // request
    contract.parmDataAreaIdRequest(nDXBVEMailRequestPerCompany.Company ? nDXBVEMailRequestPerCompany.Company : this.getCompanyFilter());
    contract.parmrecIdRequestTable(nDXBVEMailRequestPerCompany.KCS_KBVRequestTable);

    // in editMode ?
    contract.parmInEditMode(this.isInEditMode());

    return contract;
}

/// <summary>
/// PaffH 19.08.25
