/// <summary>
/// PaffH 07.08.25
/// last modified: PaffH 17.11.25
/// </summary>
/// <param name = "_nDXBVEmailRequestProcessingState">NDXBVEmailRequestProcessingState</param>
/// <param name = "_allowedit">boolean</param>
/// <returns>_allowedit</returns>
public boolean setEditModeForDatasources(NDXBVEmailRequestProcessingState _nDXBVEmailRequestProcessingState, boolean _allowedit = false)
{
    boolean allowEdit = _allowedit;
    nDXBVEMailRequestState.reread();

    if (!prmIsDefault(_allowedit))
    {
        if (_allowedit)
        {
            if (nDXBVEMailRequestState.BVEmailRequestProcessingState == NDXBVEmailRequestProcessingState::NewBVEmailRequest
                || nDXBVEMailRequestState.BVEmailRequestProcessingState == NDXBVEmailRequestProcessingState::ReleasedEmailRequest)
            {
                NDXBVEMailRequestState::statusChangedNDXBVEMailRequestState(nDXBVEMailRequestState, _nDXBVEmailRequestProcessingState);
                nDXBVEMailRequestState.write();
            }
        }
        else
        {
            if (nDXBVEMailRequestState.BVEmailRequestProcessingState == NDXBVEmailRequestProcessingState::RequestInProgress &&
                nDXBVEMailRequestState.StatusChangedBy == curUserId())

            {
                NDXBVEMailRequestState::statusChangedNDXBVEMailRequestState(nDXBVEMailRequestState, _nDXBVEmailRequestProcessingState);
                nDXBVEMailRequestState.write();
            }
        }
    }

    allowEdit = nDXBVEMailRequestState.BVEmailRequestProcessingState == NDXBVEmailRequestProcessingState::RequestInProgress &&
        nDXBVEMailRequestState.StatusChangedBy == curUserId();
    if (_allowedit && !allowEdit)
    {
        switch (nDXBVEMailRequestState.BVEmailRequestProcessingState)
        {
            case NDXBVEmailRequestProcessingState::RequestInProgress:
                warning(strFmt("@NDXBase:NDXRecordIsProcessedBy", nDXBVEMailRequestState.StatusChangedBy));
                break;
            case NDXBVEmailRequestProcessingState::RequestProcessingCompleted:
                warning(strFmt("@NDXBase:NDXRecordProcessingCompletedBy", nDXBVEMailRequestState.StatusChangedBy));
                break;
        }
    }            
    //fdsNDXBVEMailRequestState.allowEdit(allowedit);
    ////thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, NDXBVEMailRequestHeader)).allowEdit(allowedit);
    //thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, NDXBVEMailRequestLine )).allowEdit(allowedit);
    //thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, NDXBVEMailRequestADA)).allowEdit(allowedit);

    //thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonIdLookUp)).allowEdit(allowEdit);
    //thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonNameLookUp)).allowEdit(allowEdit);
    //thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonEmailAddressLookUp)).allowEdit(allowEdit);

    this.updateDesign();

    //this.setFormViewEditMode(allowedit ? ViewEditMode::Edit : ViewEditMode::View);
    return allowedit;
}

