/// <summary>
/// PaffH 08.10.25
/// </summary>
/// <param name = "_checkFormRunEditMode">boolean (true)</param>
/// <returns>in edit mode?</returns>
public boolean isInEditMode(boolean _checkFormRunEditMode = true)
{
    boolean inEditMode = nDXBVEMailRequestState.BVEmailRequestProcessingState == NDXBVEmailRequestProcessingState::RequestInProgress
        && nDXBVEMailRequestState.StatusChangedBy == curUserId();
    if (_checkFormRunEditMode)
    {
        inEditMode = inEditMode && thisFormRun.viewEditModeHelper().isInEditMode();
    }
    return inEditMode;
}

/// <summary>
/// PaffH 17.11.25
/// </summary>
/// <param name = "_viewEditMode">true - EditMode</param>
/// <returns>is in editMode</returns>
public boolean setFormViewEditMode(ViewEditMode _viewEditMode)
{
    thisFormRun.viewEditModeHelper().setViewEditMode(_viewEditMode);
    return thisFormRun.viewEditModeHelper().isInEditMode();
}

/// <summary>
/// PaffH 08.10.25
/// </summary>
/// <returns>is editable ?</returns>
public boolean isEditable()
{
    boolean editable = nDXBVEMailRequestState.BVEmailRequestProcessingState == NDXBVEmailRequestProcessingState::NewBVEmailRequest
        || nDXBVEMailRequestState.BVEmailRequestProcessingState == NDXBVEmailRequestProcessingState::ReleasedEmailRequest
        || (nDXBVEMailRequestState.BVEmailRequestProcessingState == NDXBVEmailRequestProcessingState::RequestInProgress
        && nDXBVEMailRequestState.StatusChangedBy == curUserId());
    return editable;
}

/// <summary>
/// PaffH 02.09.25
/// last modified: PaffH 01.10.25
/// </summary>
protected void updateDesign()
{
    nDXBVEMailRequestState = fdsNDXBVEMailRequestState.cursor();

    // closable ?
    boolean isInEditModeForUser = this.isInEditMode(false);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormButtonCloseBVEmailRequest)).enabled(isInEditModeForUser);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormButtonReleaseBVEmailRequest)).enabled(isInEditModeForUser);

    // editable ?
    boolean isEditable = this.isEditable();
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormButtonEditBVEmailRequest)).enabled(isEditable && !isInEditModeForUser);

    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, fmfbSmmContactsListPageLookupSmmBusRelTable)).enabled(isEditable);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, fmfbSmmContactsListPageLookupCustomer)).enabled(isEditable);

    boolean isInEditMode = this.isInEditMode();
    fdsNDXBVEMailRequestState.allowEdit(isInEditMode);
    thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, NDXBVEMailRequestLine_5)).allowEdit(isInEditMode);
    thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, NDXBVEMailRequestLineItem_5)).allowEdit(isInEditMode);
    thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, NDXBVEMailRequestADA)).allowEdit(isInEditMode);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonIdLookUp)).allowEdit(isInEditMode);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonNameLookUp)).allowEdit(isInEditMode);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonEmailAddressLookUp)).allowEdit(isInEditMode);

    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormButtonSelectItemAuto)).enabled(isInEditMode);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormButtonSelectItemManual)).enabled(isInEditMode);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormButtonItemManualDelete)).enabled(isInEditMode);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormButtonCompletionOfItemPositionProcessing))
        .enabled(isInEditMode && nDXBVEMailRequestState.ProcessingstatusOfRequestItems != NDXProcessingstatusOfRequestItems::ProcessingEnd);

    // default: not enabled            
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, AVAKBVCreateRequestTable)).enabled(false);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormMenuFunctionButtonAVAKBVBuildingProjectTable)).enabled(false);
    thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, AVAKBVRequestTable)).enabled(false);

    // display notes?
    nDXBVEMailRequestNotes = fdsNDXBVEMailRequestNotes.cursor();
    FormTabPageControl tabPageControl = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormTabPageNotes));
    tabPageControl.visible(nDXBVEMailRequestNotes.RecId > 0);
    if (nDXBVEMailRequestNotes.RecId > 0)
    {
        tabPageControl.fastTabExpanded(FastTabExpanded::Yes);
    }

}

/// <summary>
/// PaffH 13.08.25
/// last modified: PaffH 03.12.25
/// pre NDXBVEMailRequestHeader
/// </summary>
public void onActiveNDXBVEMailRequestHeader()
{
    Query q;
    FormStringControl contactPersonIdLookup = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonIdLookUp));
    FormStringControl contactPersonNameLookUp = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonNameLookUp));
    FormStringControl contactPersonEmailAddressLookUp = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonEmailAddressLookUp));

    nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
    nDXBVEMailRequestState = fdsNDXBVEMailRequestState.cursor();

    contactPersonIdLookup.text(nDXBVEMailRequestHeader.ContactPersonContactPersonId);
    contactPersonNameLookUp.text(nDXBVEMailRequestHeader.ContactPersonName);
    contactPersonEmailAddressLookUp.text(nDXBVEMailRequestHeader.ContactPersonEmail);

    nDXBVEMailRequestNotes = fdsNDXBVEMailRequestNotes.cursor();
    NDXBVEMailRequestNotes nDXBVEMailRequestNotesLocal;
    nDXBVEMailRequestNotes.setTmpData(nDXBVEMailRequestNotesLocal);
    fdsNDXBVEMailRequestNotes.research();

    boolean contactFound = false;
    boolean fdsContactPersonLookupEexecuteQuery = true;
    boolean ukChanged = false;
    DataAreaId uk;
    AccountNum accountNum;

    this.contactPersonFdsSetDefault();

    contactPersonLookUp = fdsContactPersonLookup.cursor();
    nDXBVEMailRequestState = fdsNDXBVEMailRequestState.cursor();

    // busreltable header
    if (nDXBVEMailRequestHeader.OrganisationProspectDataAreaId)
    {
        q = fdssmmBusRelTableHeader.query();
        q.clearCompanyRange();
        q.addCompanyRange(nDXBVEMailRequestHeader.OrganisationProspectDataAreaId);
        SysQuery::findOrCreateRange(fdssmmBusRelTableHeader.queryBuildDataSource(), fieldNum(smmBusRelTable,BusRelAccount)).value(queryValue(nDXBVEMailRequestHeader.OrganisationProspectProspectId));
    }
    else
    {
        SysQuery::findOrCreateRange(fdssmmBusRelTableHeader.queryBuildDataSource(), fieldNum(smmBusRelTable,BusRelAccount)).value(SysQuery::value(-1));
    }
    fdssmmBusRelTableHeader.executeQuery();
    smmBusRelTableHeader = fdssmmBusRelTableHeader.cursor();
    uk = smmBusRelTableHeader.DataAreaId;
    accountNum = smmBusRelTableHeader.BusRelAccount;

    // customer header
    if (nDXBVEMailRequestHeader.OrganisationCustomerDataAreaId)
    {
        q = fdsCustTableHeader.query();
        q.clearCompanyRange();
        q.addCompanyRange(nDXBVEMailRequestHeader.OrganisationCustomerDataAreaId);
        SysQuery::findOrCreateRange(fdsCustTableHeader.queryBuildDataSource(), fieldNum(CustTable, AccountNum)).value(queryValue(nDXBVEMailRequestHeader.OrganisationCustomerAccount));
    }
    else
    {
        SysQuery::findOrCreateRange(fdsCustTableHeader.queryBuildDataSource(), fieldNum(CustTable, AccountNum)).value(SysQuery::value(-1));
    }
    fdsCustTableHeader.executeQuery();
    custTableHeader = fdsCustTableHeader.cursor();
    uk = custTableHeader.DataAreaId;
    accountNum = custTableHeader.AccountNum;

    // dataareaid contactperson lookup
    q = fdsContactPersonLookup.query();
    container conCompany = NDXHelperDataArea::getConCompanyFromQueryCompanyRange(q);
    if (conLen(conCompany) == 1 && conPeek(conCompany,1) != this.getCompanyFilter())
    {
        q.clearCompanyRange();
        q.addCompanyRange(this.getCompanyFilter());
        ukChanged = true;
    }

    // Planer
    //nDXBVEMailRequestPlaner = fdsNDXBVEMailRequestPlaner.cursor();
    //if (nDXBVEMailRequestPlaner.IdentifierGUID != nDXBVEMailRequestHeader.IdentifierGUID)
    //{
    //    SysQuery::findOrCreateRange(fdsDirPartyTableLookUpPlaner.QueryBuildDatasource(), fieldNum(DirPartyTable, PartyNumber)).value(queryValue(-1));
    //    fdsDirPartyTableLookUpPlaner.executequery();
    //}

    // contactperson
    if (!nDXBVEMailRequestState.ContactPersonIdManualSelected && nDXBVEMailRequestHeader.ContactPersonContactPersonId)
    {
        if (nDXBVEMailRequestHeader.ContactPersonContactPersonId == contactPersonLookUp.ContactPersonId)
        {
            contactFound = true;
            fdsContactPersonLookupEexecuteQuery = false;
            SysQuery::findOrCreateRange(fdsContactPersonLookup.queryBuildDataSource(), fieldNum(ContactPerson, ContactPersonId)).value(contactPersonLookUp.ContactPersonId);
        }
        else
        {
            q = NDXContactPersonLookupClass::queryLookupContactPersonById();
            NDXContactPersonLookupClass::setDataAreaId(q, this.getCompanyFilter());
            contactPersonLookUp = NDXContactPersonLookupClass::queryRunLookupContactPersonById(q, nDXBVEMailRequestHeader.ContactPersonContactPersonId) ;
            contactFound = (contactPersonLookUp.ContactPersonId == nDXBVEMailRequestHeader.ContactPersonContactPersonId);
            if (contactFound)
            {
                this.setCompanyRange(contactPersonLookUp.DataAreaId);

                SysQuery::findOrCreateRange(fdsContactPersonLookup.queryBuildDataSource(), fieldNum(ContactPerson, ContactPersonId)).value(contactPersonLookUp.ContactPersonId);
            }
        }
    }
    else if (nDXBVEMailRequestState.ContactPersonIdManualSelected ||
        (nDXBVEMailRequestHeader.ContactPersonContactPersonId && nDXBVEMailRequestHeader.ContactPersonContactPersonId == contactPersonLookUp.ContactPersonId))
    {
        if (nDXBVEMailRequestState.ContactPersonIdManualSelected == contactPersonLookUp.ContactPersonId ||
            nDXBVEMailRequestHeader.ContactPersonContactPersonId == contactPersonLookUp.ContactPersonId)
        {
            contactFound = true;
            fdsContactPersonLookupEexecuteQuery = false;
        }
        else
        {
            q = NDXContactPersonLookupClass::queryLookupContactPersonById();
            NDXContactPersonLookupClass::setDataAreaId(q, this.getCompanyFilter());
            contactPersonLookUp = NDXContactPersonLookupClass::queryRunLookupContactPersonById(q, nDXBVEMailRequestState.ContactPersonIdManualSelected) ;
            contactFound = (contactPersonLookUp.ContactPersonId == nDXBVEMailRequestState.ContactPersonIdManualSelected);
            if (contactFound)
            {
                this.setCompanyRange(contactPersonLookUp.DataAreaId);

                SysQuery::findOrCreateRange(fdsContactPersonLookup.queryBuildDataSource(), fieldNum(ContactPerson, ContactPersonId)).value(contactPersonLookUp.ContactPersonId);
            }
        }
    }
    if (!contactFound && contactPersonIdLookup.text())      // find contact by ContactPersonId
    {
        q = NDXContactPersonLookupClass::queryLookupContactPersonById();
        NDXContactPersonLookupClass::setDataAreaId(q, this.getCompanyFilter());
        contactPersonLookUp = NDXContactPersonLookupClass::queryRunLookupContactPersonById(q, contactPersonIdLookup.text()) ;
        contactFound = (contactPersonLookUp.ContactPersonId == contactPersonIdLookup.text());
        if (contactFound)
        {
            this.setCompanyRange(contactPersonLookUp.DataAreaId);

            SysQuery::findOrCreateRange(fdsContactPersonLookup.queryBuildDataSource(), fieldNum(ContactPerson, ContactPersonId)).value(contactPersonLookUp.ContactPersonId);
        }
    }
    if (!contactFound && contactPersonNameLookUp.text())    // find contact by Name
    {
        q = NDXContactPersonLookupClass::queryLookupContactPersonByName();
        DirPartyTable dirpartyTable = NDXContactPersonLookupClass::queryRunLookupContactPersonByName(q, contactPersonNameLookUp.text());
        contactFound = (dirpartyTable.Name == contactPersonNameLookUp.text());
        if (contactFound)
        {
            this.setCompanyRange(contactPersonLookUp.DataAreaId);

            fdsDirPartyTableLookup.queryBuildDataSource().joinMode(JoinMode::InnerJoin);
            SysQuery::findOrCreateRange(fdsDirPartyTableLookup.queryBuildDataSource(), fieldNum(DirPartyTable, RecId)).value(queryValue(dirpartyTable.RecId));
        }
    }
    if (!contactFound && contactPersonEmailAddressLookUp.text())    // find contact by E-Mail
    {
        q = NDXContactPersonLookupClass::queryLookupContactPersonByEmail();
        LogisticsElectronicAddress logisticsElectronicAddress = NDXContactPersonLookupClass::queryRunLookupContactPersonByEmail(q, contactPersonEmailAddressLookUp.text());
        contactFound = (logisticsElectronicAddress.Locator == contactPersonEmailAddressLookUp.text());
        if (contactFound)
        {
            this.setCompanyRange(contactPersonLookUp.DataAreaId);

            fdsLogisticsElectronicAddressLookup.queryBuildDataSource().joinMode(JoinMode::InnerJoin);
            SysQuery::findOrCreateRange(fdsLogisticsElectronicAddressLookup.queryBuildDataSource(), fieldNum(LogisticsElectronicAddress, RecId)).value(queryValue(logisticsElectronicAddress.RecId));
        }
    }
    if (!contactFound)
    {
        SysQuery::findOrCreateRange(fdsContactPersonLookup.queryBuildDataSource(), fieldNum(ContactPerson, ContactPersonId)).value(queryValue(-1));
    }
    if (fdsContactPersonLookupEexecuteQuery || ukChanged)
    {
        fdsContactPersonLookup.executeQuery();
    }
    contactPersonLookUp = fdsContactPersonLookup.cursor();
    uk = contactPersonLookUp.DataAreaId;
    accountNum = contactPersonLookUp.ContactPersonId;
    this.updateDesign();
    this.updateStatistiks();
}

/// <summary>
/// PaffH 08.08.25
/// </summary>
/// <param name = "_callingIdControl">FormStringControl</param>
/// <param name = "currentContactPersonId">ContactPersonId</param>
/// <param name = "_callingNameControl">FormStringControl</param>
public static void lookupContactPerson(
    FormStringControl _callingIdControl,
    ContactPersonId currentContactPersonId = '',
    FormStringControl _callingNameControl = null)
{
    NDXContactPersonLookupContract contract = NDXContactPersonLookupResult::instance().parmContract();
    Args args = new Args();
    args.name(formStr(NDXContactPersonLookup));

    if (contract.parmLookupByEmail())
    {
        args.caller(_callingNameControl);
        args.lookupValue(_callingNameControl.text());
    }
    else if (contract.parmLookupByName() && _callingNameControl && _callingIdControl.text())  
    {
        contract.parmStrName(_callingNameControl.text());
        args.caller(_callingNameControl);
        args.lookupValue(_callingNameControl.text());
    }
    else
    {
        contract.parmStrId(_callingIdControl.text());
        args.caller(_callingIdControl);
        args.lookupValue(currentContactPersonId);
    }

    changecompany(contract.parmContactPersonDataAreaId())
    {
        FormRun formRun = classfactory.formRunClass(args);
        if (formRun is NDXContactPersonLookupI)
        {
            NDXContactPersonLookupI nDXContactPersonLookupI = formRun as NDXContactPersonLookupI;
            nDXContactPersonLookupI.callingNameControl(_callingNameControl);
            nDXContactPersonLookupI.callingIdControl(_callingIdControl);
        }
        formRun.init();

        if (contract.parmLookupByName() ||
        contract.parmLookupByEmail())
        {
            _callingNameControl.performFormLookup(formRun);
        }
        else
        {
            _callingIdControl.performFormLookup(formRun);
        }
    }
}

/// <summary>
/// PaffH 18.08.25
/// </summary>
/// <param name = "_contactPersonManualSelect">boolean</param>
public void checkContactPersonLookup(boolean _contactPersonManualSelect = false)
{
    //var contactPersonid = contactPersonLookup.ContactPersonId;
    //var contactPersonContactPersonId = nDXBVEMailRequestHeader.ContactPersonContactPersonId;
    //var contactPersonIdManualSelected = nDXBVEMailRequestState.ContactPersonIdManualSelected;

    contactPersonLookUp = fdsContactPersonLookup.cursor();
    nDXBVEMailRequestState = fdsNDXBVEMailRequestState.cursor();
    nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
    dirPartyTableLookup = fdsDirPartyTableLookup.cursor();
    smmBusRelTableLookup = fdssmmBusRelTableLookup.cursor();
    custTableLookup = fdsCustTableLookup.cursor();

    if (_contactPersonManualSelect)
    {
        if (nDXBVEMailRequestState.ContactPersonIdManualSelected != contactPersonLookup.ContactPersonId)
        {
            SysQuery::findOrCreateRange(fdsContactPersonLookup.queryBuildDataSource(), fieldNum(ContactPerson, ContactPersonId)).value(nDXBVEMailRequestState.ContactPersonIdManualSelected);
            fdsContactPersonLookup.executeQuery();
        }
    }

    boolean nDXBVEMailRequestStateWrite = false;
    boolean fdsNDXBVEMailRequestStateExecuteQuery = false;

    // assigned busrel
    if (nDXBVEMailRequestState.BusRelChangedManual == NoYes::No)
    {
        if ((dirPartyTableLookup.RecId == contactPersonLookup.ContactForParty &&
                    smmBusRelTableLookup.Party == dirPartyTableLookup.RecId &&
                    nDXBVEMailRequestState.smmBusRelAccountManualSelected != smmBusRelTableLookup.BusRelAccount)
                || (!smmBusRelTableLookup && nDXBVEMailRequestState.smmBusRelAccountManualSelected))
        {
            nDXBVEMailRequestState.smmBusRelAccountManualSelected = smmBusRelTableLookup.BusRelAccount;
            nDXBVEMailRequestStateWrite = true;
            fdsNDXBVEMailRequestStateExecuteQuery = true;
        }
    }
    // assigned customer
    if (nDXBVEMailRequestState.CustomerChangedManual == NoYes::No)
    {
        if ((dirPartyTableLookup.RecId == contactPersonLookup.ContactForParty &&
                    custTableLookup.Party == dirPartyTableLookup.RecId &&
                    nDXBVEMailRequestState.CustAccountManualSelected != custTableLookup.AccountNum)
                || (!custTableLookup &&  nDXBVEMailRequestState.CustAccountManualSelected))
        {
            nDXBVEMailRequestState.CustAccountManualSelected = custTableLookup.AccountNum;
            nDXBVEMailRequestStateWrite = true;
            fdsNDXBVEMailRequestStateExecuteQuery = true;
        }
    }

    if (contactPersonLookup.ContactPersonId != nDXBVEMailRequestHeader.ContactPersonContactPersonId)
    {
        if (nDXBVEMailRequestState.ContactPersonIdManualSelected != contactPersonLookup.ContactPersonId)
        {
            fdsNDXBVEMailRequestStateExecuteQuery = false;
            nDXBVEMailRequestState.ContactPersonIdManualSelected = contactPersonLookup.ContactPersonId;
            nDXBVEMailRequestState.ContactLocalization = NDXBVEmailRequestRoleLocalization::LocalizationManuallyInD365FO;
            nDXBVEMailRequestState.ContactIdentification = NDXBVEmailRequestRoleIdentification::LocalizationManuallyInD365FO;
            nDXBVEMailRequestState.ContactIdentificationStatus = NDXBVEmailRequestRoleIdentificationStatus::ChangedAssignmentInD365FO;
            nDXBVEMailRequestStateWrite = true;
        }
    }
    else
    {
        if (nDXBVEMailRequestState.ContactPersonIdManualSelected != '' ||
                nDXBVEMailRequestState.ContactLocalization != NDXBVEmailRequestRoleLocalization::LocalizationViaOutlookPlugin ||
                nDXBVEMailRequestState.ContactIdentification != NDXBVEmailRequestRoleIdentification::LocalizationViaDataEntityFromOutlookPlugin ||
                nDXBVEMailRequestState.ContactIdentificationStatus != NDXBVEmailRequestRoleIdentificationStatus::UnchangedAssignmentFromOutlookPlugin)
        {
            nDXBVEMailRequestState.ContactPersonIdManualSelected = '';
            nDXBVEMailRequestState.ContactLocalization = NDXBVEmailRequestRoleLocalization::LocalizationViaOutlookPlugin;
            nDXBVEMailRequestState.ContactIdentification = NDXBVEmailRequestRoleIdentification::LocalizationViaDataEntityFromOutlookPlugin;
            nDXBVEMailRequestState.ContactIdentificationStatus = NDXBVEmailRequestRoleIdentificationStatus::UnchangedAssignmentFromOutlookPlugin;
            nDXBVEMailRequestStateWrite = true;
        }
    }
    if (nDXBVEMailRequestStateWrite)
    {
        nDXBVEMailRequestState.write();
    }
    if (fdsNDXBVEMailRequestStateExecuteQuery)
    {
        fdsNDXBVEMailRequestState.reread();
        fdsNDXBVEMailRequestState.refresh();

        //container conCompanyRange = fdssmmBusRelTableState.query().getCompanyRange();
        //conCompanyRange = fdsCustTableState.query().getCompanyRange();
        //fdssmmBusRelTableState.executeQuery();
        fdsCustTableState.executeQuery();

    }
}

