/// <summary>
/// PaffH 03.09.25
/// </summary>
/// <param name = "_contactPerson">ContactPerson</param>
public void setContactPerson(ContactPerson _contactPerson)
{
    contactPersonLookUp = fdsContactPersonLookup.cursor();
    nDXBVEMailRequestState = fdsNDXBVEMailRequestState.cursor();
    nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
    dirPartyTableLookup = fdsDirPartyTableLookup.cursor();
    smmBusRelTableLookup = fdssmmBusRelTableLookup.cursor();
    custTableLookup = fdsCustTableLookup.cursor();

    if (contactPersonLookUp.RecId != _contactPerson.RecId)
    {
        SysQuery::findOrCreateRange(fdsContactPersonLookup.queryBuildDataSource(), fieldNum(ContactPerson, ContactPersonId)).value(queryValue(_contactPerson.ContactPersonId));
        fdsContactPersonLookup.executeQuery();
        nDXBVEMailRequestState.ContactPersonIdManualSelected = _contactPerson.ContactPersonId;
        nDXBVEMailRequestState.modifiedField(fieldNum(NDXBVEMailRequestState, ContactPersonIdManualSelected));
        DirPartyTable dirPartyTableLocal = DirPartyTable::findRec(_contactPerson.ContactForParty);
        if (dirPartyTableLocal)
        {
            CustTable custTableLocal = CustTable::findByPartyRecId(dirPartyTableLocal.RecId);
            smmBusRelTable smmBusRelTableLocal = smmBusRelTable::findByParty(dirPartyTableLocal.RecId);
            nDXBVEMailRequestState.smmBusRelAccountManualSelected = smmBusRelTableLocal.BusRelAccount;
            nDXBVEMailRequestState.modifiedField(fieldNum(NDXBVEMailRequestState, smmBusRelAccountManualSelected));
            nDXBVEMailRequestState.CustAccountManualSelected = custTableLocal.AccountNum;
            nDXBVEMailRequestState.modifiedField(fieldNum(NDXBVEMailRequestState, CustAccountManualSelected));
        }

        nDXBVEMailRequestState.write();
    }
}

