/// <summary>
/// PaffH 04.09.25
/// </summary>
public void duplicateBVEmailRequest()
{
    nDXBVEMailRequestState = fdsNDXBVEMailRequestState.cursor();
    nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
    NDXBVEMailRequestState nDXBVEMailRequestStateLocal;
    NDXBVEMailRequestHeader nDXBVEMailRequestHeaderLocal;

    buf2Buf(nDXBVEMailRequestState, nDXBVEMailRequestStateLocal);
    nDXBVEMailRequestStateLocal.insert();

    buf2Buf(nDXBVEMailRequestHeader, nDXBVEMailRequestHeaderLocal);
    nDXBVEMailRequestHeaderLocal.NDXBVEMailRequestState = nDXBVEMailRequestStateLocal.RecId;
    nDXBVEMailRequestHeaderLocal.IdentifierGUID = newGuid();
    nDXBVEMailRequestHeaderLocal.insert();

    NDXBVEMailRequestLine nDXBVEMailRequestLineFrom;
    NDXBVEMailRequestLine nDXBVEMailRequestLineTo;
    while select nDXBVEMailRequestLineFrom
        where nDXBVEMailRequestLineFrom.IdentifierGUID == nDXBVEMailRequestHeader.IdentifierGUID
    {
        buf2Buf(nDXBVEMailRequestLineFrom, nDXBVEMailRequestLineTo);
        nDXBVEMailRequestLineTo.IdentifierGUID = nDXBVEMailRequestHeaderLocal.IdentifierGUID;
        nDXBVEMailRequestLineTo.insert();
    }

    NDXBVEMailRequestADA nDXBVEMailRequestADAFrom;
    NDXBVEMailRequestADA nDXBVEMailRequestADATo;
    while select nDXBVEMailRequestADAFrom
        where nDXBVEMailRequestADAFrom.IdentifierGUID == nDXBVEMailRequestHeader.IdentifierGUID
    {
        buf2Buf(nDXBVEMailRequestADAFrom, nDXBVEMailRequestADATo);
        nDXBVEMailRequestADATo.IdentifierGUID = nDXBVEMailRequestHeaderLocal.IdentifierGUID;
        nDXBVEMailRequestADATo.insert();
    }
    fdsNDXBVEMailRequestState.executeQuery();
}

