/// <summary>
/// PaffH 06.10.25
/// last modified: PaffH 28.11.25
/// </summary>
/// <param name = "_nDXBVSearchContract">NDXBVSearchContract</param>
public void setRequestTable(NDXBVSearchContract _nDXBVSearchContract)
{
    if (_nDXBVSearchContract.parmrecIdRequestTable())
    {
        // wird nicht mehr benötigt
        //nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
        //nDXBVEMailRequestHeader.KCS_KBVRequestTable = _nDXBVSearchContract.parmrecIdRequestTable();
        //nDXBVEMailRequestHeader.update();

        // request header
        nDXBVEMailRequestPerCompany = fdsNDXBVEMailRequestPerCompany.cursor();
        nDXBVEMailRequestPerCompany.KCS_KBVRequestTable = _nDXBVSearchContract.parmrecIdRequestTable();
        if (!nDXBVEMailRequestPerCompany.validateWrite())
        {
            return;
        }
        nDXBVEMailRequestPerCompany.update();

        changecompany(nDXBVEMailRequestPerCompany.Company)
        {
            // request lines
            NDXKBVRequestLine nDXKBVRequestLine;
            NDXBVEMailRequestLine nDXBVEMailRequestLineLocal;
            QueryRun qr = new QueryRun(NDXBVEMailRequestLine::queryFromNDXBVEMailRequestPerCompany(nDXBVEMailRequestPerCompany));
            ttsbegin;
            while (qr.next())
            {
                nDXBVEMailRequestLineLocal = qr.get(tableNum(NDXBVEMailRequestLine));
                nDXKBVRequestLine = NDXKBVRequestLine::findFromNDXKBVRequestLineRecId(nDXBVEMailRequestLineLocal.NDXKBVRequestLine, true);
                nDXKBVRequestLine.initFromNDXBVEMailRequestLine(nDXBVEMailRequestLineLocal);
                if (!nDXKBVRequestLine)
                {
                    nDXKBVRequestLine.KCS_KBVRequestTable = _nDXBVSearchContract.parmrecIdRequestTable();
                    nDXKBVRequestLine.LineCreationSequenceNumber = 1;
                    if (nDXKBVRequestLine.validateWrite())
                    {
                        nDXKBVRequestLine.insert();
                    }
                    nDXBVEMailRequestLineLocal.NDXKBVRequestLine = nDXKBVRequestLine.RecId;
                    nDXBVEMailRequestLineLocal.update();

                }
                else
                {
                    if (nDXKBVRequestLine.validateWrite())
                    {
                        nDXKBVRequestLine.update();
                    }
                }
            }
            ttscommit;
        }
        this.reFreshNDXBVEMailRequestPerCompany();
    }
}

