/// <summary>
/// PaffH 13.11.25
/// last modified: PaffH 18.11.25
/// </summary>
/// <param name = "_nDXBVEMailRequestLine">NDXBVEMailRequestLine</param>
private void checkStatisticsItemSelect(NDXBVEMailRequestLine _nDXBVEMailRequestLine = null)
{
    Counter linesTotal = 0;
    Counter linesWithoutItemsAssigned = 0;
    Counter linesDeactive = 0;
    Counter linesWithManualItems = 0;
    NDXBVEMailRequestLine nDXBVEMailRequestLineLocal;
    if (_nDXBVEMailRequestLine && FormDataUtil::isFormDataSource(_nDXBVEMailRequestLine))
    {
        FormDataSource fds = FormDataUtil::getFormDataSource(_nDXBVEMailRequestLine);
        nDXBVEMailRequestLineLocal = fds.getFirst();
        while (nDXBVEMailRequestLineLocal)
        {
            ++linesTotal;
            if (!nDXBVEMailRequestLineLocal.ItemId && nDXBVEMailRequestLineLocal.Deactive == NoYes::No)
            {
                ++linesWithoutItemsAssigned;
            }
            if (nDXBVEMailRequestLineLocal.Deactive == NoYes::Yes)
            {
                ++linesDeactive;
            }
            if (nDXBVEMailRequestLineLocal.Deactive == NoYes::No
                && NDXBVEMailRequestLineItem::findFromNDXBVEMailRequestLine(nDXBVEMailRequestLineLocal).Manual == NoYes::Yes)
            {
                ++linesWithManualItems;
            }

            nDXBVEMailRequestLineLocal = fds.getNext();
        }
    }
    else
    {
        Query q = new Query();
        nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
        QueryBuildDataSource qbds = q.addDataSource(tableNum(NDXBVEMailRequestLine));

        // lines total
        qbds.addRange(fieldnum(NDXBVEMailRequestLine, IdentifierGUID)).value(queryValue(nDXBVEMailRequestHeader.IdentifierGUID));
        qbds.addSelectionField(fieldNum(NDXBVEMailRequestLine, RecId), SelectionField::Count);
        QueryRun qr = new QueryRun(q);
        qr.next();
        nDXBVEMailRequestLineLocal = qr.get(tablenum(NDXBVEMailRequestLine));
        linesTotal = int642int(nDXBVEMailRequestLineLocal.RecId);

        // lines without item assignment
        qbds.addRange(fieldNum(NDXBVEMailRequestLine, ItemId)).value(SysQuery::valueEmptyString());
        qbds.addRange(fieldNum(NDXBVEMailRequestLine, Deactive)).value(queryValue(NoYes::No));
        qr = new QueryRun(q);
        qr.next();
        nDXBVEMailRequestLineLocal = qr.get(tablenum(NDXBVEMailRequestLine));
        linesWithoutItemsAssigned = int642int(nDXBVEMailRequestLineLocal.RecId);

        // Deactive request positions
        qbds.clearRange(fieldNum(NDXBVEMailRequestLine, ItemId));
        SysQuery::findOrCreateRange(qbds, fieldNum(NDXBVEMailRequestLine, Deactive)).value(queryValue(NoYes::Yes));
        qr = new QueryRun(q);
        qr.next();
        nDXBVEMailRequestLineLocal = qr.get(tablenum(NDXBVEMailRequestLine));
        linesDeactive = int642int(nDXBVEMailRequestLineLocal.RecId);

        // Manual item assignments
        SysQuery::findOrCreateRange(qbds, fieldNum(NDXBVEMailRequestLine, Deactive)).value(queryValue(NoYes::No));
        QueryBuildDataSource qbds2 = qbds.addDataSource(tableNum(NDXBVEMailRequestLineItem));
        qbds2.addLink(fieldnum(NDXBVEMailRequestLine, IdentifierGUID), fieldNum(NDXBVEMailRequestLineItem, IdentifierGUID));
        qbds2.addLink(fieldnum(NDXBVEMailRequestLine, IdentifierLine), fieldNum(NDXBVEMailRequestLineItem, IdentifierLine));
        qbds2.addLink(fieldnum(NDXBVEMailRequestLine, ItemId), fieldNum(NDXBVEMailRequestLineItem, ItemId));
        qbds2.addLink(fieldnum(NDXBVEMailRequestLine, ItemIdDataAreaId), fieldNum(NDXBVEMailRequestLineItem, ItemIdDataAreaId));
        qbds2.addRange(fieldNum(NDXBVEMailRequestLineItem, Manual)).value(queryValue(NoYes::Yes));
        qr = new QueryRun(q);
        qr.next();
        nDXBVEMailRequestLineLocal = qr.get(tablenum(NDXBVEMailRequestLine));
        linesWithManualItems = int642int(nDXBVEMailRequestLineLocal.RecId);

    }
    FormStaticTextControl textControl = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormStaticTextLinesTotalValue));
    textControl.text(int2Str(linesTotal));

    textControl = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormStaticTextLinesWithoutItemAssignmentTotalValue));
    textControl.text(int2Str(linesWithoutItemsAssigned));
    this.setColorStaticTextControlValue(textControl, linesWithoutItemsAssigned > 0);

    textControl = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormStaticTextLinesRequestPositionDeactiveValue));
    textControl.text(int2Str(linesDeactive));

    textControl = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormStaticTextLinesManualItemAssignmentsValue));
    textControl.text(int2Str(linesWithManualItems));
}

/// <summary>
/// PaffH 17.11.25
/// </summary>
public void selectItemAuto()
{
    NDXBVEMailRequestLine nDXBVEMailRequestLineLocal;
    NDXBVEMailRequestLineItem nDXBVEMailRequestLineItemLocal;
    Query q;
    QueryBuildDataSource qbds;
    QueryRun qr;
    nDXBVEMailRequestLineLocal = fdsNDXBVEMailRequestLine_5.getFirst();
    while (nDXBVEMailRequestLineLocal)
    {
        if (nDXBVEMailRequestLineLocal.Deactive == NoYes::No && !nDXBVEMailRequestLineLocal.ItemId)
        {
            q = new Query();
            qbds = q.addDataSource(tableNum(NDXBVEMailRequestLineItem));
            qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierGUID)).value(queryValue(nDXBVEMailRequestLineLocal.IdentifierGUID));
            qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierLine)).value(queryValue(nDXBVEMailRequestLineLocal.IdentifierLine));
            qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, Manual)).value(queryValue(NoYes::Yes));
            qbds.addGroupByField(fieldNum(NDXBVEMailRequestLineItem, Manual));
            qbds.addSelectionField(fieldNum(NDXBVEMailRequestLineItem, RecId), SelectionField::Count);
            qr = new QueryRun(q);
            qr.next();
            nDXBVEMailRequestLineItemLocal = qr.get(tableNum(NDXBVEMailRequestLineItem));
            if (nDXBVEMailRequestLineItemLocal.RecId == 1)
            {
                q = new Query();
                qbds = q.addDataSource(tableNum(NDXBVEMailRequestLineItem));
                qbds.update(true);
                qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierGUID)).value(queryValue(nDXBVEMailRequestLineLocal.IdentifierGUID));
                qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierLine)).value(queryValue(nDXBVEMailRequestLineLocal.IdentifierLine));
                qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, Manual)).value(queryValue(NoYes::Yes));
                qr = new QueryRun(q);
                qr.next();
                nDXBVEMailRequestLineItemLocal = qr.get(tableNum(NDXBVEMailRequestLineItem));
                this.selectItemAutoDoUpdate(nDXBVEMailRequestLineItemLocal, nDXBVEMailRequestLineLocal);
            }
            else
            {
                q = new Query();
                qbds = q.addDataSource(tableNum(NDXBVEMailRequestLineItem));
                qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierGUID)).value(queryValue(nDXBVEMailRequestLineLocal.IdentifierGUID));
                qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierLine)).value(queryValue(nDXBVEMailRequestLineLocal.IdentifierLine));
                qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, Manual)).value(queryValue(NoYes::No));
                qbds.addGroupByField(fieldNum(NDXBVEMailRequestLineItem, HitProbabilityInPercent));
                qbds.addSelectionField(fieldNum(NDXBVEMailRequestLineItem, RecId), SelectionField::Count);
                qbds.addOrderByField(fieldNum(NDXBVEMailRequestLineItem, HitProbabilityInPercent), SortOrder::Descending);
                qr = new QueryRun(q);
                qr.next();
                nDXBVEMailRequestLineItemLocal = qr.get(tableNum(NDXBVEMailRequestLineItem));
                if (nDXBVEMailRequestLineItemLocal.RecId == 1)
                {
                    q = new Query();
                    qbds = q.addDataSource(tableNum(NDXBVEMailRequestLineItem));
                    qbds.update(true);
                    qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierGUID)).value(queryValue(nDXBVEMailRequestLineLocal.IdentifierGUID));
                    qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierLine)).value(queryValue(nDXBVEMailRequestLineLocal.IdentifierLine));
                    qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, Manual)).value(queryValue(NoYes::No));
                    qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, HitProbabilityInPercent)).value(queryValue(nDXBVEMailRequestLineItemLocal.HitProbabilityInPercent));
                    qr = new QueryRun(q);
                    qr.next();
                    nDXBVEMailRequestLineItemLocal = qr.get(tableNum(NDXBVEMailRequestLineItem));
                    this.selectItemAutoDoUpdate(nDXBVEMailRequestLineItemLocal, nDXBVEMailRequestLineLocal);
                }
            }
        }

        nDXBVEMailRequestLineLocal = fdsNDXBVEMailRequestLine_5.getNext();
    }

    fdsNDXBVEMailRequestLine_5.executeQuery();
    fdsNDXBVEMailRequestLineItem_5.executeQuery();

}

/// <summary>
/// PaffH 17.11.25
/// </summary>
/// <param name = "_nDXBVEMailRequestLineItem">NDXBVEMailRequestLineItem</param>
/// <param name = "_nDXBVEMailRequestLine">NDXBVEMailRequestLine</param>
private void selectItemAutoDoUpdate(NDXBVEMailRequestLineItem _nDXBVEMailRequestLineItem, NDXBVEMailRequestLine _nDXBVEMailRequestLine)
{
    _nDXBVEMailRequestLineItem.SelectItem = NoYes::Yes;
    ttsbegin;
    _nDXBVEMailRequestLineItem.update();
    ttscommit;

    _nDXBVEMailRequestLine.ItemId = _nDXBVEMailRequestLineItem.ItemId;
    _nDXBVEMailRequestLine.ItemIdDataAreaId = _nDXBVEMailRequestLineItem.ItemIdDataAreaId;
    _nDXBVEMailRequestLine.update();

    NDXBVEMailRequestLineItem::checkItemSelect(_nDXBVEMailRequestLineItem);
    this.checkStatisticsItemSelect(_nDXBVEMailRequestLine);
}

/// <summary>
/// PaffH 18.11.25
/// Complete position processing
/// </summary>
public void completionOfItemPositionProcessing()
{
    NDXBVEMailRequestLine nDXBVEMailRequestLineLocal;
    nDXBVEMailRequestHeader = fdsBVEmailRequestHeader.cursor();
    Query q = new Query();
    QueryBuildDataSource qbds = q.addDataSource(tableNum(NDXBVEMailRequestLine));
    qbds.addRange(fieldNum(NDXBVEMailRequestLine, IdentifierGUID)).value(queryValue(nDXBVEMailRequestHeader.IdentifierGUID));
    qbds.addRange(fieldNum(NDXBVEMailRequestLine, ItemId)).value(SysQuery::valueEmptyString());
    qbds.addRange(fieldNum(NDXBVEMailRequestLine, Deactive)).value(queryValue(NoYes::No));
    qbds.addSelectionField(fieldNum(NDXBVEMailRequestLine, RecId), SelectionField::Count);
    QueryRun qr = new QueryRun(q);
    qr.next();
    nDXBVEMailRequestLineLocal = qr.get(tableNum(NDXBVEMailRequestLine));
    if (nDXBVEMailRequestLineLocal.RecId)
    {
        warning(strFmt("@NDX:NDXItemProcessingCantBeCompleted", nDXBVEMailRequestLineLocal.RecId));
        return;
    }
}

